abstract class Product{String id,name;double price;Product(String i,String n,double p){id=i;name=n;price=p;}abstract double calculateDiscount();}class Electronics extends Product{Electronics(String i,String n,double p){super(i,n,p);}double calculateDiscount(){return price*.1;}}class ProductDiscount{public static void main(String[] a){Product p=new Electronics("1","Laptop",50000);System.out.println(p.price-p.calculateDiscount());}}